#!/bin/bash
# regenerate record.json + summary.txt from the committed run logs (repo root)
D=results/rtl/s81_layer_tput_1013; T=$D/runs; X=$D/families.json; O=$D/record.json
python3 tools/s81_ctrl/die_layer_tput.py --run phier=$T/phier:nom:L0,L2,L14:"production: NG 256, hierarchical HC slab, nominal link" --run shier=$T/shier:nom:L0,L2,L14:"production + --coef-split" --run pflat=$T/pflat:nom:L0,L2,L14:"NG 256, flat HC engine" --run phier_base=$T/phier_base:base:L0:"production with injected link errors (EPER 97)" --run n16=$T/n16:nom:L0,L2,L14:"reduced NG 16 flat, nominal" --run s16=$T/s16:nom:L0,L2,L14:"reduced NG 16 flat + --coef-split" --run h16=$T/h16:nom:L0:"NG 16 hierarchical" --run base16=$T/base16:base:L0,L2:"reduced NG 16 flat, link errors (the 10-13 07:48 record)" --run base16_L14=$T/base16_L14:base:L14:"reduced, L14" --mut phier_mhc=$T/phier_mhc:mut_hc:L0 --mut phier_mcoll=$T/phier_mcoll:mut_coll:L0 --mut base16_mhc=$T/base16:mut_hc:L0 --mut base16_mcoll=$T/base16:mut_coll:L0 --mut L14_mhc=$T/base16_L14:mut_hc:L14 --mut L14_mcoll=$T/base16_L14:mut_coll:L14 --mut lvm54_mhc=$T/lvm54_mhc:mut_hc:L0 --lvm lvm10=$T/lvm10:10 --lvm lvm30=$T/lvm30:30 --lvm lvm54=$T/lvm54:54 --primary phier --split shier --extra $X --out $O > $D/summary.txt 2>&1
